\begin{theorem}[Shrinking breathers are gradient solitons]
\label{thm:chow-ii-appd-shrinking-breathers}
\source{chow-et-al-ricci-flow-part-ii:page-0402}
\uses{lem:chow-ii-appd-mu-monotonicity}
\dcref{appD:D.40}
\group{Perelman Invariants}


Every shrinking Ricci breather on a closed manifold is a gradient shrinking
Ricci soliton.
\end{theorem}

